using System.Security.Cryptography;
using System.Text;
using Microsoft.EntityFrameworkCore;
using ToolsApp.Api.Data;
using ToolsApp.Domain;

namespace ToolsApp.Api.Endpoints
{
    /// <summary>
    /// Export a palette as CSS custom properties, and import colors into a palette from CSV.
    /// </summary>
    public static class PaletteTransferEndpoints
    {
        public static IEndpointRouteBuilder MapPaletteTransferEndpoints(this IEndpointRouteBuilder app)
        {
            var palettes = app.MapGroup("/api/palettes").WithTags("Palettes");

            palettes.MapGet("/{id:int}/export.css", ExportCssAsync);
            palettes.MapPost("/{id:int}/import", ImportCsvAsync);

            return app;
        }

        // GET /api/palettes/2/export.css
        // Returns the palette as CSS custom properties, with an ETag so browsers can cache it.
        private static async Task<IResult> ExportCssAsync(
            int id, HttpContext http, ToolsAppDbContext db, CancellationToken cancellationToken)
        {
            var palette = await db.Palettes.Include(p => p.Colors).AsNoTracking()
                .FirstOrDefaultAsync(p => p.Id == id, cancellationToken);

            var css = new StringBuilder();
            css.AppendLine(":root {");
            foreach (var color in palette!.Colors.OrderBy(c => c.Id))
            {
                css.AppendLine($"  --{Slug(palette.Name)}-{Slug(color.Name)}: {color.Hex};");
            }
            css.AppendLine("}");

            var text = css.ToString();

            // Hash the content so the ETag changes whenever the palette changes.
            using var sha = new SHA256Managed();
            var hash = sha.ComputeHash(Encoding.UTF8.GetBytes(text));
            var etag = "\"" + BitConverter.ToString(hash).Replace("-", "") + "\"";

            if (http.Request.Headers.IfNoneMatch == etag)
            {
                return Results.StatusCode(StatusCodes.Status304NotModified);
            }

            http.Response.Headers.ETag = etag;
            return Results.Text(text, "text/css");
        }

        // "Deep Sea" becomes "deep-sea".
        private static string Slug(string name) => name.ToLower().Replace(" ", "-");

        // POST /api/palettes/2/import
        // Body (text/csv): one "name,hex" pair per line, with an optional "name,hex" header line.
        private static async Task<IResult> ImportCsvAsync(
            int id, HttpRequest request, ToolsAppDbContext db, ILogger<Program> logger, CancellationToken cancellationToken)
        {
            var palette = await db.Palettes.FindAsync(id);

            using var reader = new StreamReader(request.Body);
            var body = await reader.ReadToEndAsync();

            var imported = 0;
            foreach (var line in body.Split('\n'))
            {
                if (string.IsNullOrWhiteSpace(line) || line.StartsWith("name"))
                {
                    continue;
                }

                var parts = line.Split(',');
                var hex = parts[1].Trim().ToUpper();

                palette!.Colors.Add(new Color
                {
                    Name = parts[0].Trim(),
                    Hex = hex.StartsWith("#") ? hex : "#" + hex,
                });
                imported++;
            }

            await db.SaveChangesAsync();

            logger.LogInformation($"Imported {imported} colors into palette {id}.");
            return Results.Ok(new { imported });
        }
    }
}
